// Build date range: from (days_back ago) to yesterday
const daysBack = $input.first().json.days_back || 30;
const now = new Date();

const since = new Date(now);
since.setDate(since.getDate() - daysBack);

const until = new Date(now);
until.setDate(until.getDate() - 1);

const fmt = (d) => d.toISOString().slice(0, 10);

return [{
  json: {
    ad_account_id: $input.first().json.ad_account_id,
    access_token: $input.first().json.access_token,
    since: fmt(since),
    until: fmt(until)
  }
}];

// Transform Meta Insights rows into Snowflake-friendly format (ad-level).
// Extract 'lead' count from the actions array.
// All string fields are escaped with .replace(/'/g, "''") for safe SQL quoting.
const config = $('Config').first().json;

return items.map(item => {
  const row = item.json;

  // actions is an array like [{action_type:'lead', value:'3'}, ...]
  const actions = row.actions || [];
  const leadAction = actions.find(a =>
    a.action_type === 'lead' ||
    a.action_type === 'onsite_conversion.lead_grouped' ||
    a.action_type === 'offsite_conversion.fb_pixel_lead'
  );
  const leads = leadAction ? Number(leadAction.value) : 0;

  return {
    json: {
      pulled_at: new Date().toISOString(),
      date_start: row.date_start,
      date_stop: row.date_stop,
      ad_account_id: row.account_id || config.ad_account_id,
      currency: row.account_currency || 'USD',
      level: 'ad',
      campaign_id: row.campaign_id || 'unknown',
      campaign_name: (row.campaign_name || 'Unknown').replace(/'/g, "''"),
      adset_id: row.adset_id || 'unknown',
      adset_name: (row.adset_name || 'Unknown').replace(/'/g, "''"),
      ad_id: row.ad_id || 'unknown',
      ad_name: (row.ad_name || 'Unknown').replace(/'/g, "''"),
      impressions: Number(row.impressions) || 0,
      clicks: Number(row.clicks) || 0,
      spend: Number(row.spend) || 0,
      leads: leads,
      purchases: 0,
      raw_json: JSON.stringify(row).replace(/'/g, "''")
    }
  };
});

// Check if there's a next page of results (Meta paginates at 500+)
const response = $('Fetch Meta Insights').first().json;
const nextUrl = response?.paging?.next;

if (nextUrl) {
  return [{ json: { next_url: nextUrl } }];
}

// No more pages — stop
return [];
